class Solution {
public:
    long long maximumLinearStockScore(vector<int>& prices) {
        unordered_map<long long, long long> buckets;
        long long best = LLONG_MIN;
        for (int i = 0; i < prices.size(); i++) {
            long long d = prices[i] - (i + 1);
            buckets[d] += prices[i];
            best = max(best, buckets[d]);
        }
        return best;
    }
};

c.java:
class Solution {
    public long maximumLinearStockScore(int[] prices) {
        Map<Long, Long> buckets = new HashMap<>();
        long best = Long.MIN_VALUE;
        for (int i = 0; i < prices.length; i++) {
            long d = prices[i] - (i + 1);
            buckets.merge(d, (long) prices[i], Long::sum);
            best = Math.max(best, buckets.get(d));
        }
        return best;
    }
}

