var maximumLinearStockScore = function(prices) {
    const buckets = new Map();
    let best = -Infinity;
    prices.forEach((p, i) => {
        const d = p - (i + 1);
        buckets.set(d, (buckets.get(d) || 0) + p);
        best = Math.max(best, buckets.get(d));
    });
    return best;
};
